48	  @Test
49	  public void testSliceTo() {
50	    final int size = 64 * 1024;
51	    ByteBuffer buffer = ByteBuffer.allocate(size);
52	    // fill the buffer with data
53	    IntBuffer intBuffer = buffer.asIntBuffer();
54	    for(int i=0; i < size / Integer.BYTES; ++i) {
55	      intBuffer.put(i);
56	    }
57	    // ensure we don't make unnecessary slices
58	    ByteBuffer slice = VectoredReadUtils.sliceTo(buffer, 100,
59	        FileRange.createFileRange(100, size));
60	    Assertions.assertThat(buffer)
61	            .describedAs("Slicing on the same offset shouldn't " +
62	                    "create a new buffer")
63	            .isEqualTo(slice);
64	    Assertions.assertThat(slice.position())
65	        .describedAs("Slicing should return buffers starting from position 0")
66	        .isEqualTo(0);
67	
68	    // try slicing a range
69	    final int offset = 100;
70	    final int sliceStart = 1024;
71	    final int sliceLength = 16 * 1024;
72	    slice = VectoredReadUtils.sliceTo(buffer, offset,
73	        FileRange.createFileRange(offset + sliceStart, sliceLength));
74	    // make sure they aren't the same, but use the same backing data
75	    Assertions.assertThat(buffer)
76	            .describedAs("Slicing on new offset should " +
77	                    "create a new buffer")
78	            .isNotEqualTo(slice);
79	    Assertions.assertThat(buffer.array())
80	            .describedAs("Slicing should use the same underlying " +
81	                    "data")
82	            .isEqualTo(slice.array());
83	    Assertions.assertThat(slice.position())
84	        .describedAs("Slicing should return buffers starting from position 0")
85	        .isEqualTo(0);
86	    // test the contents of the slice
87	    intBuffer = slice.asIntBuffer();
88	    for(int i=0; i < sliceLength / Integer.BYTES; ++i) {
89	      assertEquals("i = " + i, i + sliceStart / Integer.BYTES, intBuffer.get());
90	    }
91	  }
