880	  /**
881	   * {@inheritDoc}
882	   * Vectored read implementation for S3AInputStream.
883	   * @param ranges the byte ranges to read.
884	   * @param allocate the function to allocate ByteBuffer.
885	   * @throws IOException IOE if any.
886	   */
887	  @Override
888	  public void readVectored(List<? extends FileRange> ranges,
889	                           IntFunction<ByteBuffer> allocate) throws IOException {
890	    LOG.debug("Starting vectored read on path {} for ranges {} ", pathStr, ranges);
891	    checkNotClosed();
892	    if (stopVectoredIOOperations.getAndSet(false)) {
893	      LOG.debug("Reinstating vectored read operation for path {} ", pathStr);
894	    }
895	    List<? extends FileRange> sortedRanges = validateNonOverlappingAndReturnSortedRanges(ranges);
896	    for (FileRange range : ranges) {
897	      validateRangeRequest(range);
898	      CompletableFuture<ByteBuffer> result = new CompletableFuture<>();
899	      range.setData(result);
900	    }
901	
902	    if (isOrderedDisjoint(sortedRanges, 1, minSeekForVectorReads())) {
903	      LOG.debug("Not merging the ranges as they are disjoint");
904	      streamStatistics.readVectoredOperationStarted(sortedRanges.size(), sortedRanges.size());
905	      for (FileRange range: sortedRanges) {
906	        ByteBuffer buffer = allocate.apply(range.getLength());
907	        boundedThreadPool.submit(() -> readSingleRange(range, buffer));
908	      }
909	    } else {
910	      LOG.debug("Trying to merge the ranges as they are not disjoint");
911	      List<CombinedFileRange> combinedFileRanges = mergeSortedRanges(sortedRanges,
912	              1, minSeekForVectorReads(),
913	              maxReadSizeForVectorReads());
914	      streamStatistics.readVectoredOperationStarted(sortedRanges.size(), combinedFileRanges.size());
915	      LOG.debug("Number of original ranges size {} , Number of combined ranges {} ",
916	              ranges.size(), combinedFileRanges.size());
917	      for (CombinedFileRange combinedFileRange: combinedFileRanges) {
918	        boundedThreadPool.submit(
919	            () -> readCombinedRangeAndUpdateChildren(combinedFileRange, allocate));
920	      }
921	    }
922	    LOG.debug("Finished submitting vectored read to threadpool" +
923	            " on path {} for ranges {} ", pathStr, ranges);
924	  }
