226	  /**
227	   * Validate a list of ranges (including overlapping checks) and
228	   * return the sorted list.
229	   * <p>
230	   * Two ranges overlap when the start offset
231	   * of second is less than the end offset of first.
232	   * End offset is calculated as start offset + length.
233	   * @param input input list
234	   * @param fileLength file length if known
235	   * @return a new sorted list.
236	   * @throws IllegalArgumentException if there are overlapping ranges or
237	   * a range element is invalid (other than with negative offset)
238	   * @throws EOFException if the last range extends beyond the end of the file supplied
239	   *                      or a range offset is negative
240	   */
241	  public static List<? extends FileRange> validateAndSortRanges(
242	      final List<? extends FileRange> input,
243	      final Optional<Long> fileLength) throws EOFException {
244	
245	    requireNonNull(input, "Null input list");
246	    checkArgument(!input.isEmpty(), "Empty input list");
247	    final List<? extends FileRange> sortedRanges;
248	
249	    if (input.size() == 1) {
250	      validateRangeRequest(input.get(0));
251	      sortedRanges = input;
252	    } else {
253	      sortedRanges = sortRanges(input);
254	      FileRange prev = null;
255	      for (final FileRange current : sortedRanges) {
256	        validateRangeRequest(current);
257	        if (prev != null) {
258	          checkArgument(current.getOffset() >= prev.getOffset() + prev.getLength(),
259	              "Overlapping ranges %s and %s", prev, current);
260	        }
261	        prev = current;
262	      }
263	    }
264	    // at this point the final element in the list is the last range
265	    // so make sure it is not beyond the end of the file, if passed in.
266	    // where invalid is defined as: last range's offset + length > filelength.
267	    if (fileLength.isPresent()) {
268	      final FileRange last = sortedRanges.get(sortedRanges.size() - 1);
269	      final Long l = fileLength.get();
270	      // this check is against the last range, but as the list is sorted
271	      // it is also a check against the entire set of ranges.
272	      if (last.getOffset() + last.getLength() > l) {
273	        throw new EOFException("Range " + last
274	            + " is beyond the end of the file " + l);
275	      }
276	    }
277	    return sortedRanges;
278	  }
